package com.example.inventory.dao;import java.sql.*;public final class Database{private static final String URL="jdbc:sqlite:inventory.db";private Database(){}public static Connection connect()throws SQLException{Connection c=DriverManager.getConnection(URL);try(Statement s=c.createStatement()){s.execute("PRAGMA foreign_keys=ON");}return c;}public static void initializeDatabase()throws SQLException{try(Connection c=connect();Statement s=c.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS vendors(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,contact_info TEXT)");s.executeUpdate("CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>=0),vendor_id INTEGER,FOREIGN KEY(vendor_id) REFERENCES vendors(id) ON DELETE SET NULL)");s.executeUpdate("CREATE TABLE IF NOT EXISTS stock_entries(id INTEGER PRIMARY KEY AUTOINCREMENT,item_id INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),type TEXT NOT NULL CHECK(type IN ('IN','OUT')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE)");}}}